def lca(node, a, b):
    """Lowest common ancestor of values a and b in a BST, or None if either is missing."""
    while node is not None:
        v = node[0]
        if a < v and b < v:
            node = node[1]
        elif a > v and b > v:
            node = node[2]
        else:
            return v
    return None

